draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw a stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw a fruit
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20 * Math.sin(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'red';
  ctx.fill();

  // draw a vegetable
  ctx.beginPath();
  ctx.rect(W/2 + 30 + 20 * Math.cos(t), H/2 - 30, 20, 20);
  ctx.stroke();
  ctx.fillStyle = 'green';
  ctx.fill();

  ctx.restore();
}
